CREATE TYPE "UserRole" AS ENUM ('staff','manager');
CREATE TYPE "PeriodStatus" AS ENUM ('collecting','reviewing','published');
CREATE TABLE "stores" ("id" UUID PRIMARY KEY, "name" TEXT NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "store_settings" ("store_id" UUID PRIMARY KEY REFERENCES "stores"("id") ON DELETE CASCADE, "business_start_time" TIME NOT NULL DEFAULT '07:00', "business_end_time" TIME NOT NULL DEFAULT '20:00', "shift_interval_minutes" INTEGER NOT NULL DEFAULT 30 CHECK ("shift_interval_minutes" IN (15,30,60)), "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK ("business_start_time" < "business_end_time"));
CREATE TABLE "users" ("id" UUID PRIMARY KEY, "store_id" UUID NOT NULL REFERENCES "stores"("id") ON DELETE RESTRICT, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "password_hash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'staff', "is_active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "users_store_id_is_active_idx" ON "users"("store_id","is_active");
CREATE TABLE "shift_periods" ("id" UUID PRIMARY KEY, "store_id" UUID NOT NULL REFERENCES "stores"("id") ON DELETE RESTRICT, "year" INTEGER NOT NULL, "month" INTEGER NOT NULL CHECK ("month" BETWEEN 1 AND 12), "status" "PeriodStatus" NOT NULL DEFAULT 'collecting', "submission_deadline" TIMESTAMPTZ NOT NULL, "published_at" TIMESTAMPTZ, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("store_id","year","month"));
CREATE INDEX "shift_periods_store_id_status_idx" ON "shift_periods"("store_id","status");
CREATE TABLE "shift_requests" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "shift_period_id" UUID NOT NULL REFERENCES "shift_periods"("id") ON DELETE CASCADE, "date" DATE NOT NULL, "start_time" TIME, "end_time" TIME, "is_day_off" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("user_id","shift_period_id","date"), CHECK (("is_day_off" AND "start_time" IS NULL AND "end_time" IS NULL) OR (NOT "is_day_off" AND "start_time" IS NOT NULL AND "end_time" IS NOT NULL AND "start_time" < "end_time")));
CREATE INDEX "shift_requests_shift_period_id_user_id_idx" ON "shift_requests"("shift_period_id","user_id");
CREATE TABLE "shift_submissions" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "shift_period_id" UUID NOT NULL REFERENCES "shift_periods"("id") ON DELETE CASCADE, "submitted_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("user_id","shift_period_id"));
CREATE INDEX "shift_submissions_shift_period_id_idx" ON "shift_submissions"("shift_period_id");
CREATE TABLE "confirmed_shifts" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "shift_period_id" UUID NOT NULL REFERENCES "shift_periods"("id") ON DELETE CASCADE, "date" DATE NOT NULL, "start_time" TIME, "end_time" TIME, "is_day_off" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("user_id","shift_period_id","date"), CHECK (("is_day_off" AND "start_time" IS NULL AND "end_time" IS NULL) OR (NOT "is_day_off" AND "start_time" IS NOT NULL AND "end_time" IS NOT NULL AND "start_time" < "end_time")));
CREATE INDEX "confirmed_shifts_shift_period_id_user_id_idx" ON "confirmed_shifts"("shift_period_id","user_id");
